import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def count_divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def check_condition(n, divisors):
    if len(divisors) < 5:
        return False

    # Divisors are 1-indexed in the problem description (2nd, 3rd, 5th smallest)
    # In the list (0-indexed), these correspond to index 1, 2, 4.
    a = divisors[1] # Second smallest
    b = divisors[2] # Third smallest
    c = divisors[4] # Fifth smallest

    lhs = n
    rhs = a*b + a*c + b*c

    return lhs == rhs

# Store the tau(n) values found
found_tau_values = set()
results = {}

# Search up to n=1000
for n in range(1, 1001):
    tau_n = count_divisors(n)

    if tau_n >= 5:
        divs = get_divisors(n)

        if check_condition(n, divs):
            found_tau_values.add(tau_n)
            results[n] = tau_n

print(f"Total solutions found up to n=1000: {len(results)}")
print(f"All solutions n: {results}")
print(f"Set of tau(n) values: {found_tau_values}")

